head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .centered-bottom {
  position: relative;
}
body#layout .section.featured-post,
body#layout .section.main,
body#layout .section.vertical-ad-container {
  float: left;
  width: 55%;
}
body#layout .sidebar-container {
  display: inline-block;
  width: 39%;
}
body#layout .centered-bottom:after {
  clear: both;
  content: "";
  display: table;
}
body#layout .hamburger-menu,
body#layout .search {
  display: none;
}

div.script:
//
document.addEventListener("DOMContentLoaded", function () {
    // Tạo nút toggle sidebar
    var toggleBtn = document.createElement('button');
    toggleBtn.className = 'sidebar-toggle-btn';
    toggleBtn.innerHTML = '☰';
    toggleBtn.setAttribute('aria-label', 'Mở menu');
    document.body.appendChild(toggleBtn);

    // Tạo overlay
    var overlay = document.createElement('div');
    overlay.className = 'sidebar-overlay';
    document.body.appendChild(overlay);

    // Lấy sidebar container
    var sidebar = document.querySelector('.sidebar-container');

    if (sidebar) {
        // Tạo nút đóng trong sidebar
        var closeBtn = document.createElement('button');
        closeBtn.className = 'sidebar-close-btn';
        closeBtn.innerHTML = '✕';
        closeBtn.setAttribute('aria-label', 'Đóng menu');
        sidebar.insertBefore(closeBtn, sidebar.firstChild);

        // Tạo menu mobile trong sidebar
        var mobileMenu = document.createElement('div');
        mobileMenu.className = 'sidebar-mobile-menu';
        mobileMenu.innerHTML = '<a href="/"> Trang chủ</a>' +
            '<a href="javascript:void(0)" class="dropdown-toggle" id="sidebar-category-toggle"> Danh mục</a>' +
            '<div class="menu-dropdown-mobile" id="sidebar-category-dropdown">' +
            '<a href="/search/label/Hoa%20T%E1%BA%B7ng">Hoa Tặng</a>' +
            '<a href="/search/label/Hoa%20Trang%20Tr%C3%AD">Hoa Trang Trí</a>' +
            '</div>' +
            '<a href="/p/gioi-thieu.html"> Giới thiệu</a>';
        sidebar.insertBefore(mobileMenu, closeBtn.nextSibling);

        // Tạo phần search trong sidebar
        var searchWrapper = document.createElement('div');
        searchWrapper.className = 'sidebar-search-wrapper';
        searchWrapper.innerHTML = '<form action="/search">' +
            '<input type="text" name="q" placeholder="Tìm kiếm sản phẩm..." autocomplete="off"/>' +
            '<button type="submit" aria-label="Tìm kiếm">' +
            '<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">' +
            '<path d="M15.5 14h-.79l-.28-.27A6.471 6.471 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/>' +
            '</svg>' +
            '</button>' +
            '</form>';
        sidebar.insertBefore(searchWrapper, mobileMenu.nextSibling);

        // Tạo phần cờ ngôn ngữ trong sidebar
        var flagsWrapper = document.createElement('div');
        flagsWrapper.className = 'sidebar-flags-wrapper';
        flagsWrapper.innerHTML = '<span>Ngôn ngữ:</span>' +
            '<button class="flag-btn" onclick="selectVietnam()" title="Tiếng Việt" type="button">' +
            '<img alt="Vietnam" src="https://flagcdn.com/w40/vn.png"/>' +
            '</button>' +
            '<button class="flag-btn" onclick="selectKorea()" title="Tiếng Hàn" type="button">' +
            '<img alt="Korea" src="https://flagcdn.com/w40/kr.png"/>' +
            '</button>';
        sidebar.insertBefore(flagsWrapper, searchWrapper.nextSibling);

        // Xử lý dropdown toggle
        var categoryToggle = document.getElementById('sidebar-category-toggle');
        var categoryDropdown = document.getElementById('sidebar-category-dropdown');
        if (categoryToggle && categoryDropdown) {
            categoryToggle.addEventListener('click', function () {
                this.classList.toggle('open');
                categoryDropdown.classList.toggle('open');
            });
        }

        // Hàm mở sidebar
        function openSidebar() {
            sidebar.classList.add('sidebar-open');
            overlay.classList.add('active');
            toggleBtn.classList.add('active');
            toggleBtn.innerHTML = '✕';
            document.body.style.overflow = 'hidden';
        }

        // Hàm đóng sidebar
        function closeSidebar() {
            sidebar.classList.remove('sidebar-open');
            overlay.classList.remove('active');
            toggleBtn.classList.remove('active');
            toggleBtn.innerHTML = '☰';
            document.body.style.overflow = '';
        }

        // Sự kiện click nút toggle
        toggleBtn.addEventListener('click', function () {
            if (sidebar.classList.contains('sidebar-open')) {
                closeSidebar();
            } else {
                openSidebar();
            }
        });

        // Sự kiện click nút đóng
        closeBtn.addEventListener('click', closeSidebar);

        // Sự kiện click overlay
        overlay.addEventListener('click', closeSidebar);

        // Đóng sidebar khi nhấn phím Escape
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && sidebar.classList.contains('sidebar-open')) {
                closeSidebar();
            }
        });
    }
});
//
